from jsonb_to_recordset($products$[{"id": "b689c6cf-2d18-51e5-8abd-3501e2243421", "name": "قميص نوم شامبين طويل بالدانتيل", "description": "لون شامبين، حمالات رفيعة وتفاصيل دانتيل على الصدر والحافة الجانبية مع قصّة غير متماثلة.", "image": "https://damascus-shop.com/images/ayla/20261101/29827.jpg", "translations": {"en": {"name": "Champagne long nightdress with lace"}, "de": {"name": "Langes champagnerfarbenes Nachthemd mit Spitze"}}}, {"id": "b52ea54f-3146-5c6c-b8da-0774cb8ca6eb", "name": "قميص نوم وردي طويل بالدانتيل", "description": "قميص طويل وردي بحمالات وربطات صغيرة وتفاصيل دانتيل على الصدر والجوانب.", "image": "https://damascus-shop.com/images/ayla/20261101/29826.jpg", "translations": {"en": {"name": "Pink long nightdress with lace"}, "de": {"name": "Langes rosa Nachthemd mit Spitze"}}}, {"id": "54787232-3c64-586f-ba69-8fe57f9ffedb", "name": "قميص نوم أبيض طويل بتفاصيل ريش", "description": "تصميم أبيض طويل بتفاصيل ريش عند الصدر وأكمام شفافة منسدلة وتفاصيل دانتيل عند الخصر.", "image": "https://damascus-shop.com/images/ayla/20261101/29825.jpg", "translations": {"en": {"name": "White long nightdress with feather details"}, "de": {"name": "Langes weißes Nachthemd mit Federdetails"}}}, {"id": "451ad42b-f3b5-5b8e-bdee-80f7b74ab00d", "name": "قميص نوم بنفسجي طويل بالدانتيل", "description": "لون بنفسجي داكن مع دانتيل على الصدر والجوانب وربطات عند الكتفين.", "image": "https://damascus-shop.com/images/ayla/20261101/29824.jpg", "translations": {"en": {"name": "Purple long nightdress with lace"}, "de": {"name": "Langes violettes Nachthemd mit Spitze"}}}, {"id": "d3e67404-163e-53c0-a531-2da29f1e98ef", "name": "قميص نوم زمردي طويل بالدانتيل", "description": "تصميم طويل باللون الأخضر الزمردي، بحمالات وتفاصيل دانتيل على الصدر والجوانب.", "image": "https://damascus-shop.com/images/ayla/20261101/29823.jpg", "translations": {"en": {"name": "Emerald long nightdress with lace"}, "de": {"name": "Langes smaragdgrünes Nachthemd mit Spitze"}}}, {"id": "9dfe172b-4465-524e-8bb6-a3f83c07dae3", "name": "قميص نوم وردي طويل بتفاصيل ريش", "description": "تصميم وردي طويل بتفاصيل ريش عند الصدر وأكمام شفافة منسدلة وتفاصيل دانتيل عند الخصر.", "image": "https://damascus-shop.com/images/ayla/20261101/29822.jpg", "translations": {"en": {"name": "Pink long nightdress with feather details"}, "de": {"name": "Langes rosa Nachthemd mit Federdetails"}}}, {"id": "41533446-b729-527d-b929-c7088cfb9f9f", "name": "طقم نوم أبيض طويل مع روب دانتيل", "description": "طقم أبيض طويل مع روب بأكمام شفافة وحواف دانتيل وحزام عند الخصر.", "image": "https://damascus-shop.com/images/ayla/20261101/29821.jpg", "translations": {"en": {"name": "White long nightwear set with lace robe"}, "de": {"name": "Langes weißes Nachtwäsche-Set mit Spitzenmantel"}}}, {"id": "da741aaf-0f1a-5549-9293-de156c6e4e86", "name": "طقم نوم أبيض قصير مع روب بقبعة", "description": "طقم أبيض قصير مع روب شفاف بقبعة وحواف دانتيل وأكمام واسعة.", "image": "https://damascus-shop.com/images/ayla/20261101/29820.jpg", "translations": {"en": {"name": "White short nightwear set with hooded robe"}, "de": {"name": "Kurzes weißes Nachtwäsche-Set mit Kapuzenmantel"}}}]$products$::jsonb)
as r(id uuid,name text,description text,image text,translations jsonb)
